import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';class ProductInformation extends StatelessWidget {  const ProductInformation({super.key});  @override  Widget build(BuildContext context) {    return Column(      crossAxisAlignment: CrossAxisAlignment.start,      mainAxisSize: MainAxisSize.max,      children: [        // Title and Stock Badge        Row(          crossAxisAlignment: CrossAxisAlignment.start,          children: [            Expanded(              child: Text(                "Natural wood and Linen Sofa Bed",                style:                TextStyle(fontSize: 22.sp, fontWeight: FontWeight.bold),              ),            ),            Container(              padding: EdgeInsets.symmetric(horizontal: 8, vertical: 4),              decoration: BoxDecoration(                color: Colors.green.shade100,                borderRadius: BorderRadius.circular(12),              ),              child: Text(                "In Stock",                style: TextStyle(color: Colors.green, fontSize: 12.sp),              ),            ),          ],        ),        SizedBox(height: 8),        // Dimensions        Text(          "120×160×195 cm - off white",          style: TextStyle(fontSize: 14.sp, color: Colors.grey.shade700),        ),        SizedBox(height: 8),        // Rating and Reviews        Row(          children: [            // Star Ratings            ...List.generate(                5,                    (index) =>                    Icon(Icons.star, color: Colors.orange, size: 18.sp)),            SizedBox(width: 5),            Text(              "5.0",              style: TextStyle(                  fontSize: 14.sp,                  fontWeight: FontWeight.bold,                  color: Colors.black),            ),            SizedBox(width: 5),            Text(              "(121 Reviews)",              style: TextStyle(fontSize: 14.sp, color: Colors.grey.shade500),            ),          ],        ),        SizedBox(height: 8),        // Price        Row(          children: [            Text(              "\$80.00",              style: TextStyle(                  fontSize: 20.sp,                  fontWeight: FontWeight.bold,                  color: Colors.black),            ),            SizedBox(width: 8),            Text(              "\$100.00",              style: TextStyle(                fontSize: 18.sp,                fontWeight: FontWeight.bold,                color: Colors.grey,                decoration: TextDecoration.lineThrough,              ),            ),          ],        ),        SizedBox(height: 12),        // Description        Text(          "It is a long established fact that a reader will be distracted by the readable content of a page when looking at its layout. "              "The point of using Lorem Ipsum is that it has a more-or-less normal distribution of letters.",          style: TextStyle(fontSize: 14.sp, color: Colors.black87),        ),        SizedBox(height: 16),        // Color Options        Text("Color",            style: TextStyle(fontSize: 16.sp, fontWeight: FontWeight.bold)),        SizedBox(height: 8),        Row(          children: [            _buildColorOption(Colors.red),            _buildColorOption(Colors.blue),            _buildColorOption(Colors.black),            _buildColorOption(Colors.orange),            _buildColorOption(Colors.green),            _buildColorOption(Colors.yellow),          ],        ),        SizedBox(height: 16),        // Size Options        Text("Size",            style: TextStyle(fontSize: 16.sp, fontWeight: FontWeight.bold)),        SizedBox(height: 8),        Row(          children: [            _buildSizeOption("S", selected: true),            _buildSizeOption("M"),            _buildSizeOption("L"),            _buildSizeOption("XL"),          ],        ),      ],    );  }  // Color Option Widget  Widget _buildColorOption(Color color) {    return Container(      margin: EdgeInsets.only(right: 8),      width: 28,      height: 28,      decoration: BoxDecoration(        color: color,        shape: BoxShape.circle,        border: Border.all(color: Colors.grey.shade300, width: 1),      ),    );  }  // Size Option Widget  Widget _buildSizeOption(String size, {bool selected = false}) {    return Container(      margin: EdgeInsets.only(right: 8),      padding: EdgeInsets.symmetric(horizontal: 12, vertical: 8),      decoration: BoxDecoration(        color: selected ? Colors.black : Colors.white,        borderRadius: BorderRadius.circular(8),        border: Border.all(color: Colors.black),      ),      child: Text(        size,        style: TextStyle(            color: selected ? Colors.white : Colors.black, fontSize: 14.sp),      ),    );  }}